CREATE TABLE IF NOT EXISTS iam.role_assignment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES iam.account(id) ON DELETE RESTRICT, role_id uuid NOT NULL REFERENCES iam.role(id) ON DELETE RESTRICT, status varchar(16) NOT NULL DEFAULT 'ACTIVE', valid_from timestamptz NOT NULL, valid_to timestamptz, granted_by uuid, grant_reason text NOT NULL, revoked_by uuid, revoked_at timestamptz, revoke_reason text, created_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS iam.assignment_scope_ceiling (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_assignment_id uuid NOT NULL REFERENCES iam.role_assignment(id) ON DELETE RESTRICT, scope_type varchar(24) NOT NULL, org_unit_id uuid NOT NULL REFERENCES org.org_unit(id) ON DELETE RESTRICT, org_unit_type_snapshot varchar(16) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(role_assignment_id, org_unit_id));
